const el=(tag,text)=>{const n=document.createElement(tag);if(text)n.textContent=text;return n;};
const money=n=>(n/100).toLocaleString('da-DK',{style:'currency',currency:'DKK'});
export function appendBankPayment(container,order){
 if(order.paymentProvider!=='bank_transfer')return;
 const box=el('details'),title=el('summary','Faktura og bankbetaling'),feedback=el('p'),bank=order.bankPayment||{},link=el('a','Åbn fakturagrundlag til bogholder');
 box.className='bank-payment';link.href='/api/admin/checkouts/'+encodeURIComponent(order.id)+'/invoice-basis';link.target='_blank';link.rel='noopener';
 box.append(title,el('p','Når hele betalingen er registreret, starter overdragelsen til PF automatisk. Ved tryk skal kunden efterfølgende godkende PF’s korrektur.'),el('p','Financial Outsourcing laver fakturaen og sender den til dig. Send den til kunden fra hello@smerch.dk. Reg. 9070 · Konto 1637329428.'),link,el('p',`Ordre: ${money(order.totalIncVat)} · Modtaget: ${money(bank.received||0)} · Rest: ${money(Math.max(0,order.totalIncVat-(bank.received||0)))}`));
 async function post(body){const response=await fetch('/api/admin/checkouts/'+encodeURIComponent(order.id)+'/bank-payment',{method:'POST',credentials:'same-origin',headers:{'Content-Type':'application/json','X-Smerch-Admin':'1'},body:JSON.stringify(body)}),result=await response.json();if(!response.ok)throw Error(result.error);location.reload();}
 if(bank.invoicedAt)box.append(el('p','✓ Faktura sendt · '+new Date(bank.invoicedAt).toLocaleString('da-DK',{timeZone:'Europe/Copenhagen'})));
 else{const sent=el('button','Faktura sendt');sent.type='button';sent.onclick=async()=>{if(!confirm('Har du sendt fakturaen til kunden fra hello@smerch.dk?'))return;sent.disabled=true;try{await post({action:'invoice_sent',confirmed:true});}catch(e){feedback.textContent=e.message;sent.disabled=false;}};box.append(sent);}
 if(!bank.invoiceNumber&&!bank.invoicedAt){const form=el('form'),label=el('label','Fakturanummer fra e-conomic'),input=el('input'),save=el('button','Registrér udstedt og sendt faktura');input.required=true;input.maxLength=100;label.append(input);form.append(label,save);form.onsubmit=async e=>{e.preventDefault();save.disabled=true;try{await post({action:'invoice',invoiceNumber:input.value});}catch(e){feedback.textContent=e.message;save.disabled=false;}};box.append(form);}
 else if(bank.invoiceNumber)box.append(el('p','Fakturanummer: '+bank.invoiceNumber));
 if((bank.invoiceNumber||bank.invoicedAt)&&order.status==='awaiting_bank_payment'){const form=el('form'),amount=el('input'),reference=el('input'),confirmed=el('input'),save=el('button','Registrér betaling · send ved fuld betaling');amount.type='number';amount.min='0.01';amount.step='0.01';amount.required=true;amount.max=((order.totalIncVat-(bank.received||0))/100).toFixed(2);reference.required=true;reference.maxLength=200;confirmed.type='checkbox';confirmed.required=true;for(const [text,input] of [['Modtaget beløb i kr.',amount],['Betalingsreference fra bogholderen eller banken',reference],['Jeg har bekræftelse på, at beløbet er modtaget på bankkontoen',confirmed]]){const label=el('label',text);label.append(input);form.append(label);}form.append(save);form.onsubmit=async e=>{e.preventDefault();save.disabled=true;try{await post({action:'receipt',amount:Math.round(Number(amount.value)*100),reference:reference.value,confirmed:confirmed.checked});}catch(e){feedback.textContent=e.message;save.disabled=false;}};box.append(form);}
 if(order.status==='paid'&&order.pfHandoff?.status!=='submitted'&&!order.pfReview?.required){const send=el('button','Kontrollér og send betalt ordre til PF');send.type='button';send.onclick=async()=>{send.disabled=true;try{const r=await fetch('/api/admin/checkouts/'+encodeURIComponent(order.id)+'/retry-handoff',{method:'POST',headers:{'X-Smerch-Admin':'1'}}),result=await r.json();if(!r.ok||result.pfHandoff?.status!=='submitted')throw Error(result.error||result.pfHandoff?.reason||'Ordren kunne ikke sendes.');location.reload();}catch(e){feedback.textContent=e.message;send.disabled=false;}};box.append(send);}
 box.append(feedback);container.append(box);
}
